export class TextureAtlasIndex {
    bounds = [0, 0];
    setBounds(bounds) {
        this.bounds = bounds;
    }
    getIndex(x, y) {
        return x + y * this.bounds[0];
    }
    getPosition(index, position = [0, 0]) {
        position[0] = Math.floor(index % this.bounds[0]);
        position[1] = Math.floor(index / this.bounds[0]);
        return position;
    }
}
